import {Edit} from 'alinea'

const blog = Edit.create({
  type: Blog,
  root: 'pages',
  set: {title: 'Blog'}
})

const posts = postData.map(data =>
  Edit.create({
    type: BlogPost,
    root: 'pages',
    parentId: blog.id,
    set: {title: data.title}
  })
)

await cms.commit(blog, ...posts)

import {Config, Edit, Field} from 'alinea'

const body = Field.richText('Body')
const sections = Field.list('Sections', {
  schema: {
    Text: Config.type('Text', {
      fields: {
        title: Field.text('Title'),
        text: body
      }
    })
  }
})

const text = Edit.richText(body)
  .addHtml('<h2>Main heading</h2><p>Parsed from <strong>HTML</strong>.</p>')
  .value()

const rows = Edit.list(sections)
  .add('Text', {title: 'The row title', text})
  .value()

